 @Test void formalExitBlocksPrivateFeedbackAndTenantEvaluationWritesWithoutPlatformSpillover(){
  UUID t=task(shared);var target=new com.dreamcore.workspace.feedback.FeedbackService.Target("TASK",t,0,0,"task-v1",0);var assessment=new com.dreamcore.workspace.feedback.FeedbackService.Assessment("PARTIAL",List.of("DATA_GAP"),"私人评价");var feedback=feedbacks.create(owner,tenant,UUID.randomUUID(),target,assessment);
  // A private task remains private even when it was run in an exportable shared workspace.
  UUID exit=UUID.randomUUID();db.update("INSERT INTO departure_executions(id,tenant_id,kind,state,requested_by,reason,policy_key,policy_revision,effective_at,deadline,prior_tenant_status) VALUES (?,?,'TENANT_EXIT','EXPORT_WINDOW',?,'合成退出事实','TENANT_EXIT_WINDOW',0,?,?, 'ACTIVE')",exit,tenant,owner,java.sql.Timestamp.from(now),java.sql.Timestamp.from(now.plus(Duration.ofDays(30))));
  db.update("INSERT INTO departure_export_grants(execution_id,tenant_id,account_id,workspace_id) VALUES (?,?,?,?)",exit,tenant,owner,shared);db.update("INSERT INTO governance_capabilities(tenant_id,account_id,capability,granted_by) VALUES (?,?,'BULK_EXPORT',?)",tenant,owner,owner);
  denied(403,()->service.get(owner,tenant,"TASK",t));denied(409,()->service.act(owner,tenant,"TASK",t,UUID.randomUUID(),1,"TRASH",false));
  denied(403,()->feedbacks.get(owner,tenant,feedback.id()));denied(403,()->feedbacks.preferences(owner,tenant));denied(403,()->feedbacks.lookup(owner,tenant,target));
  var body=new com.dreamcore.workspace.evaluation.EvaluationService.Content("合成样例","REGRESSION","仅合成",List.of(),"input","expected","observed","");
  denied(409,()->evaluations.create(owner,tenant,shared,UUID.randomUUID(),"SAMPLE",body,List.of()));denied(409,()->methods.adopt(owner,tenant,null,UUID.randomUUID(),0,"STOP",null,false));
  assertFalse(evaluations.scope(owner,tenant,shared).canMaintain());assertFalse(methods.selection(owner,tenant,null).canAdopt());assertNotNull(evaluations.create(platform,null,null,UUID.randomUUID(),"SAMPLE",body,List.of()).id());
 }
 @Test void experiencePurgeRevokesExactDeparturePackageAndErasesChunks(){
  UUID v=experience(shared,now),entry=db.queryForObject("SELECT entry_id FROM experience_versions WHERE id=?",UUID.class,v),exit=UUID.randomUUID(),set=UUID.randomUUID(),part=UUID.randomUUID(),generation=UUID.randomUUID();
  db.update("INSERT INTO departure_executions(id,tenant_id,kind,state,requested_by,reason,policy_key,policy_revision,effective_at,deadline,prior_tenant_status) VALUES (?,?,'TENANT_EXIT','CLEANING',?,'合成清理事实','TENANT_EXIT_WINDOW',0,?,?, 'ACTIVE')",exit,tenant,owner,java.sql.Timestamp.from(now.minus(Duration.ofDays(31))),java.sql.Timestamp.from(now.minus(Duration.ofDays(1))));
  db.update("INSERT INTO departure_export_sets(id,execution_id,tenant_id,owner_id,workspace_id,include_history,item_count,created_at) VALUES (?,?,?,?,?,false,1,?)",set,exit,tenant,owner,shared,java.sql.Timestamp.from(now));db.update("INSERT INTO departure_export_parts(id,set_id,number,state,request_count,lease_token,lease_until,generation,created_at) VALUES (?,?,1,'GENERATING',1,?,?,?,?)",part,set,UUID.randomUUID(),java.sql.Timestamp.from(now.plusSeconds(60)),generation,java.sql.Timestamp.from(now));db.update("INSERT INTO departure_export_items(set_id,ordinal,kind,object_id,version_id,version,size_bytes,part_id,state,filename,sha256) VALUES (?,1,'EXPERIENCE_VERSION',?,?,1,6,?,'INCLUDED','私密经验.json',?)",set,entry,v,part,"a".repeat(64));db.update("INSERT INTO departure_archive_chunks(part_id,generation,ordinal,content) VALUES (?,?,0,?)",part,generation,"SECRET".getBytes());
  UUID record=db.queryForObject("SELECT id FROM object_lifecycle WHERE kind='EXPERIENCE_VERSION' AND object_id=?",UUID.class,v);db.update("UPDATE object_lifecycle SET state='PURGE_PENDING' WHERE id=?",record);cleanup.clean(record);
  assertEquals("REVOKED",db.queryForObject("SELECT state FROM departure_export_parts WHERE id=?",String.class,part));assertNull(db.queryForObject("SELECT lease_token FROM departure_export_parts WHERE id=?",UUID.class,part));assertEquals("COMPLETE",db.queryForObject("SELECT cleanup_state FROM departure_export_parts WHERE id=?",String.class,part));assertEquals(0,db.queryForObject("SELECT count(*) FROM departure_archive_chunks WHERE part_id=?",Integer.class,part));assertNull(db.queryForObject("SELECT filename FROM departure_export_items WHERE part_id=?",String.class,part));
 }
